    <script type="module">
        /  PREMIUM LIQUID SHADER  
           Generates a Macstyle moving aurora background
        /
        const canvas = document.getElementById('canvasbg');
        const renderer = new THREE.WebGLRenderer({ canvas, alpha: false }); // Black base
        renderer.setSize(window.innerWidth, window.innerHeight);

        // Custom Shader
        const vertexShader = 
            varying vec2 vUv;
            void main() {
                vUv = uv;
                gl_Position = projectionMatrix  modelViewMatrix  vec4(position, 1.0);
            }
        ;

        const fragmentShader = 
            uniform float time;
            varying vec2 vUv;

            // Noise function
            vec3 mod289(vec3 x) { return x  floor(x  (1.0 / 289.0))  289.0; }
            vec2 mod289(vec2 x) { return x  floor(x  (1.0 / 289.0))  289.0; }
            vec3 permute(vec3 x) { return mod289(((x34.0)+1.0)x); }

            float snoise(vec2 v) {
                const vec4 C = vec4(0.211324865405187, 0.366025403784439, 0.577350269189626, 0.024390243902439);
                vec2 i  = floor(v + dot(v, C.yy) );
                vec2 x0 = v    i + dot(i, C.xx);
                vec2 i1;
                i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
                vec4 x12 = x0.xyxy + C.xxzz;
                x12.xy = i1;
                i = mod289(i);
                vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 )) + i.x + vec3(0.0, i1.x, 1.0 ));
                vec3 m = max(0.5  vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
                m = mm; m = mm;
                vec3 x = 2.0  fract(p  C.www)  1.0;
                vec3 h = abs(x)  0.5;
                vec3 ox = floor(x + 0.5);
                vec3 a0 = x  ox;
                m = 1.79284291400159  0.85373472095314  ( a0a0 + hh );
                vec3 g;
                g.x  = a0.x   x0.x  + h.x   x0.y;
                g.yz = a0.yz  x12.xz + h.yz  x12.yw;
                return 130.0  dot(m, g);
            }

            void main() {
                // Slow flowing movement
                float t = time  0.2;

                // Base colors (MacBook Pro aesthetic: Deep Purple, Blue, Black)
                vec3 c1 = vec3(0.05, 0.0, 0.15); // Deep Purple
                vec3 c2 = vec3(0.0, 0.1, 0.4);   // Deep Blue
                vec3 c3 = vec3(0.0, 0.0, 0.0);   // Black
                vec3 c4 = vec3(0.0, 0.6, 0.8);   // Cyan Accent

                float n1 = snoise(vUv  2.0 + vec2(t  0.5, t  0.2));
                float n2 = snoise(vUv  3.0  vec2(t  0.3, t  0.8));

                vec3 color = mix(c1, c2, n1);
                color = mix(color, c3, smoothstep(0.3, 0.8, n2));

                // Add subtle "aurora" lines
                float lines = sin(vUv.y  20.0 + n1  5.0 + time);
                color += c4  0.05  smoothstep(0.9, 1.0, lines);

                gl_FragColor = vec4(color, 1.0);
            }
        ;

        const scene = new THREE.Scene();
        const camera = new THREE.OrthographicCamera(1, 1, 1, 1, 0, 1);
        const uniforms = { time: { value: 0 } };
        const material = new THREE.ShaderMaterial({ vertexShader, fragmentShader, uniforms });
        const plane = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material);
        scene.add(plane);

        function animate(time) {
            uniforms.time.value = time  0.001;
            renderer.render(scene, camera);
            requestAnimationFrame(animate);
        }
        animate(0);

        window.addEventListener('resize', () => {
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        /  APP LOGIC  /
        const state = {
            chats: [
                {id: 1, title: "AI Trendek 2025"},
                {id: 2, title: "Piaci elemzés: NVDA"},
                {id: 3, title: "Python script refaktorálás"}
            ],
            activeId: null
        };

        const dom = {
            feed: document.getElementById('chatfeed'),
            input: document.getElementById('msginput'),
            hist: document.getElementById('historylist'),
            sidebar: document.getElementById('sidebar'),
            ctxMenu: document.getElementById('ctxmenu')
        };

        // Initialize
        renderHistory();
        addMessage("TiffyTime System", "Rendszer kész. Miben segíthetek ma?", 'ai');

        // Listeners
        document.getElementById('plusbtn').onclick = (e) => {
            e.stopPropagation();
            dom.ctxMenu.classList.toggle('visible');
        };

        document.onclick = (e) => {
            if (!dom.ctxMenu.contains(e.target)) dom.ctxMenu.classList.remove('visible');
        };

        document.getElementById('mobilemenubtn').onclick = () => dom.sidebar.classList.add('active');
        document.getElementById('closesidebar').onclick = () => dom.sidebar.classList.remove('active');

        document.getElementById('sendbtn').onclick = sendMsg;
        dom.input.onkeypress = (e) => { if(e.key === 'Enter') sendMsg(); };

        document.getElementById('optresearch').onclick = () => {
            dom.input.placeholder = "Kutatás célja...";
            dom.ctxMenu.classList.remove('visible');
            dom.input.focus();
        };

        document.getElementById('optfile').onclick = () => {
            document.getElementById('hiddenfile').click();
            dom.ctxMenu.classList.remove('visible');
        };

        document.getElementById('hiddenfile').onchange = (e) => {
            if(e.target.files[0]) addMessage("User", 📄 Fájl: ${e.target.files[0].name}, 'user');
        };

        document.getElementById('newchat').onclick = () => {
            dom.feed.innerHTML = '';
            addMessage("System", "Új munkamenet. Parancs?", 'ai');
            dom.sidebar.classList.remove('active');
        };

        document.getElementById('closeoverlay').onclick = () => {
            document.getElementById('researchoverlay').classList.remove('active');
        };

        // Functions
        function renderHistory() {
            dom.hist.innerHTML = state.chats.map(c => 
                <div class="historyitem" onclick="loadChat(${c.id})">${c.title}</div>
            ).join('');
        }

        function sendMsg() {
            const txt = dom.input.value.trim();
            if (!txt) return;

            addMessage("User", txt, 'user');
            dom.input.value = '';

            // Mock Logic
            if (txt.toLowerCase().includes("kutatás") || txt.toLowerCase().includes("research")) {
                setTimeout(() => startResearch(txt), 500);
            } else {
                setTimeout(() => typeReply("Feldolgozás..."), 600);
            }
        }

        function addMessage(sender, text, type) {
            const div = document.createElement('div');
            div.className = msg-group ${type};
            div.innerHTML = 
                <div class="msgmeta">${sender}</div>
                <div class="msgbubble">${text}</div>
            ;
            dom.feed.appendChild(div);
            dom.feed.scrollTop = dom.feed.scrollHeight;
        }

        function typeReply(text) {
            addMessage("TiffyTime", text, 'ai');
        }

        function startResearch(topic) {
            const id = Date.now();
            const div = document.createElement('div');
            div.className = msg-group ai;
            div.innerHTML = 
                <div class="msgmeta">ACTIVE TASK</div>
                <div class="researchwidget" onclick="openReport('${topic}')">
                    <div class="rwheader">
                        <span>Mélyelemzés</span>
                        <span>RUNNING</span>
                    </div>
                    <div class="rwtitle">${topic}</div>
                    <div class="rwprogressbg">
                        <div class="rwprogressfill" id="prog${id}"></div>
                    </div>
                </div>
            ;
            dom.feed.appendChild(div);
            dom.feed.scrollTop = dom.feed.scrollHeight;

            // Simulate
            setTimeout(() => document.getElementById(prog-${id}).style.width = "40%", 1000);
            setTimeout(() => document.getElementById(prog-${id}).style.width = "80%", 2500);
            setTimeout(() => {
                document.getElementById(prog-${id}).style.width = "100%";
                document.getElementById(prog-${id}).style.background = "30D158"; // Green
            }, 4000);
        }

        window.openReport = (topic) => {
            const content = document.getElementById('overlaycontent');
            content.innerHTML = 
                <h2>Jelentés: ${topic}</h2>
                <div class="bentogrid">
                    <div class="bentobox">
                        <div class="boxlabel">Relevancia</div>
                        <div class="boxval" style="color:var(accentprimary)">98%</div>
                    </div>
                    <div class="bentobox">
                        <div class="boxlabel">Források</div>
                        <div class="boxval">14 db</div>
                    </div>
                    <div class="bentobox">
                        <div class="boxlabel">Kockázat</div>
                        <div class="boxval" style="color:FF453A">Alacsony</div>
                    </div>
                </div>
                <div class="textcontent">
                    <p>Az AI elemzés alapján a téma iránti érdeklődés exponenciálisan növekszik. A legfontosabb piaci szereplők már integrálták stratégiájukba. (Ez egy demo szöveg, a valódi backend ide töltené be az adatokat.)</p>
                    <br>
                    <p style="color:var(accentprimary)">> Kulcsfontosságú megállapítások generálása...</p>
                </div>
            ;
            document.getElementById('researchoverlay').classList.add('active');
        };

    </script>
</body>
</html>
